package knowledge

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"sort"
	"strings"
	"sync"
)

// The runtime catalog and internal index are generated by
// scripts/import-master-database.py from the user-maintained master database.
// Keeping them separate preserves the distinction between documented UI
// controls and raw serialized .pgtx evidence.
//
//go:embed pigments_master_catalog.json
var rawMasterCatalog []byte

//go:embed pigments_internal_index.json
var rawInternalIndex []byte

var (
	runtimeOnce sync.Once
	runtimeData RuntimeMasterCatalog
	indexData   RuntimeInternalIndex
	runtimeErr  error
)

type RuntimeMasterCatalog struct {
	SchemaVersion  string                `json:"schema_version"`
	Product        string                `json:"product"`
	TargetVersion  string                `json:"target_version"`
	SourceDatabase RuntimeSourceDatabase `json:"source_database"`
	Statistics     RuntimeStatistics     `json:"statistics"`
	Notes          []string              `json:"notes"`
	Sections       []RuntimeSection      `json:"sections"`
	SampleBrowser  RuntimeSampleBrowser  `json:"sample_browser"`
}

type RuntimeSourceDatabase struct {
	Name                  string `json:"name"`
	SchemaVersion         string `json:"schema_version"`
	DataRevision          string `json:"data_revision"`
	LastUpdated           string `json:"last_updated"`
	PluginBuild           string `json:"plugin_build"`
	VersionKnowledgeState string `json:"version_knowledge_state"`
}

